  `to_pokemon_id` int(10) unsigned NOT NULL,
  `stage` tinyint(3) unsigned NOT NULL DEFAULT 1 COMMENT '1 = base -> stage 1, 2 = stage 1 -> stage 2',
  `trigger_name` varchar(50) DEFAULT NULL,
