  KEY `idx_evolutions_from` (`from_pokemon_id`),
  KEY `idx_evolutions_to` (`to_pokemon_id`),
  CONSTRAINT `fk_evo_from_pokemon` FOREIGN KEY (`from_pokemon_id`) REFERENCES `pokemon` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_evo_to_pokemon` FOREIGN KEY (`to_pokemon_id`) REFERENCES `pokemon` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
