DROP TABLE IF EXISTS `pokemon_lore`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pokemon_lore` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `pokemon_id` int(10) unsigned NOT NULL,
  `version_name` varchar(50) NOT NULL,
  `game_era` varchar(50) DEFAULT NULL,
  `flavor_text` text NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_poke_version` (`pokemon_id`,`version_name`),
  KEY `idx_pl_pokemon` (`pokemon_id`),
  CONSTRAINT `fk_pl_pokemon` FOREIGN KEY (`pokemon_id`) REFERENCES `pokemon` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14781 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
