--
-- Table structure for table `pokemon_moves`
--

DROP TABLE IF EXISTS `pokemon_moves`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pokemon_moves` (
  `pokemon_id` int(10) unsigned NOT NULL,
  `move_id` int(10) unsigned NOT NULL,
  `level_learned_at` smallint(5) unsigned NOT NULL DEFAULT 0,
  `learn_method` varchar(30) NOT NULL DEFAULT 'level-up',
  PRIMARY KEY (`pokemon_id`,`move_id`,`learn_method`),
  KEY `idx_pm_pokemon_level` (`pokemon_id`,`level_learned_at`),
  KEY `fk_pm_move` (`move_id`),
  CONSTRAINT `fk_pm_move` FOREIGN KEY (`move_id`) REFERENCES `moves` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_pm_pokemon` FOREIGN KEY (`pokemon_id`) REFERENCES `pokemon` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

