DROP TABLE IF EXISTS `pokemon_types`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pokemon_types` (
  `pokemon_id` int(10) unsigned NOT NULL,
  `type_id` int(10) unsigned NOT NULL,
  `slot` tinyint(3) unsigned NOT NULL COMMENT '1 = primary, 2 = secondary',
  PRIMARY KEY (`pokemon_id`,`slot`),
  UNIQUE KEY `uq_pokemon_type_pair` (`pokemon_id`,`type_id`),
  KEY `idx_pt_type_id` (`type_id`),
  CONSTRAINT `fk_pt_pokemon` FOREIGN KEY (`pokemon_id`) REFERENCES `pokemon` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_pt_type` FOREIGN KEY (`type_id`) REFERENCES `types` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
